list_purchase_orders.beforeRequest:
const filters = ["supplierANID", "documentNumber", "orderStatus", "routingStatus", "startDate", "endDate"].filter(name => inputs[name]).map(name => name + " eq '" + inputs[name] + "'");
if (filters.length) request.query['$filter'] = filters.join(' and ');
for (const name of ['top', 'skip']) if (Number(inputs[name])) request.query['$' + name] = inputs[name];
const form = value => encodeURIComponent(value).replace(/[!'()~]/g, c => '%' + c.charCodeAt(0).toString(16).toUpperCase()).replace(/%20/g, '+');
const pairs = Object.keys(request.query).map(key => form(key) + '=' + form(request.query[key]));
if (pairs.length) request.url += '?' + pairs.join('&');
request.query = {};
return request;

